<script lang="ts">
import {onMount,onDestroy,tick} from 'svelte';
import {api,type Draft,type Shelf,type Book} from '../../lib/api';
import BookCover from './BookCover.svelte';
import LookupCover from './LookupCover.svelte';
export let showCoverPreview=false;
export let busyChanged:(value:boolean)=>void=()=>{};export let externalBusy=false;export let draft:Draft;export let shelves:Shelf[]=[];export let editing:Book|null=null;export let saved:(b:Book)=>void;
type Lookup={draft:Draft;fetched_at:string;cached:boolean;warning?:string};
let fetched:Lookup|null=null;let lookupBusy=false;let lookupError='';
async function refresh(){if(!editing)return;lookupBusy=true;lookupError='';fetched=null;try{fetched=await api<Lookup>(`/api/books/${editing.id}/metadata/refresh`,{});}catch(e){lookupError=(e as Error).message;}finally{lookupBusy=false;}}
function useDetails(){if(!fetched)return;draft={...draft,...fetched.draft};authors=draft.authors.join(', ');fetched=null;}
let titleInput:HTMLInputElement;let errorMessage:HTMLElement;let savedReceipt:Book|null=null;let authorsDraft=draft;let authors=draft.authors.join(', ');let shelf:number|''='';let shelfTouched=false;let preferencesPending=!editing;let preferenceWarning='';let busy=false;let error='';let key='';
onMount(()=>{titleInput?.focus({preventScroll:showCoverPreview});if(!editing)api<{default_shelf_id:number|null}>('/api/preferences').then(p=>{if(!shelfTouched&&!busy&&p.default_shelf_id)shelf=p.default_shelf_id;}).catch(()=>{preferenceWarning='Default shelf could not be loaded. Choose a shelf for this book.';}).finally(()=>preferencesPending=false);});onDestroy(()=>{busyChanged(false);if(matchTimer)clearTimeout(matchTimer);matchSequence++;});
function returnToSave(event:KeyboardEvent){if(event.key==='Enter'&&!event.isComposing&&!event.repeat&&!event.shiftKey&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&event.target instanceof HTMLInputElement){event.preventDefault();if(!busy&&!lookupBusy&&!externalBusy)(event.currentTarget as HTMLFormElement).requestSubmit();}}
$: busyChanged(busy||lookupBusy);
$: if(draft!==authorsDraft){authors=draft.authors.join(', ');authorsDraft=draft;}
let matches:Book[]=[];let matchTimer:ReturnType<typeof setTimeout>|undefined;let matchSequence=0;let matchWarning='';
$: scheduleMatches(draft.title,draft.isbn,editing,savedReceipt);
function scheduleMatches(title:string,isbn:string,edit:Book|null,receipt:Book|null){if(matchTimer)clearTimeout(matchTimer);const sequence=++matchSequence;matches=[];matchWarning='';if(edit||receipt||isbn.trim()||title.trim().length<3)return;matchTimer=setTimeout(async()=>{try{const result=await api<{books:Book[]}>(`/api/books?q=${encodeURIComponent(title.trim())}`);if(sequence===matchSequence)matches=result.books.slice(0,3)}catch{if(sequence===matchSequence)matchWarning='Possible existing books could not be checked. You can still save.'}},400)}
async function showError(message:string){error=message;await tick();errorMessage?.focus();}
async function submit(e:SubmitEvent){e.preventDefault();if(busy||lookupBusy||externalBusy||preferencesPending||(!editing&&savedReceipt))return;error='';if(!draft.title.trim()){error='Enter a title for this book.';titleInput?.focus();return;}if(new TextEncoder().encode(draft.title.trim()).length>500){error='This title is too long. Shorten it and try again.';titleInput?.focus();return;}if(new TextEncoder().encode(draft.subtitle||'').length>1000){await showError('This subtitle is too long. Shorten it and try again.');return;}busy=true;const body={isbn:draft.isbn,title:draft.title,subtitle:draft.subtitle||'',publisher:draft.publisher,publication_date:draft.publication_date,source_url:draft.source_url||'',source_id:draft.source_id||'',authors:authors.split(',').map(a=>a.trim()).filter(Boolean),shelf_id:shelf?Number(shelf):null};const payload=JSON.stringify(body);if(new TextEncoder().encode(payload).length>64000){busy=false;await showError('These details are too long to save. Shorten the text and try again.');return;}if(!key)key=crypto.randomUUID();try{const b=await api<Book>(editing?`/api/books/${editing.id}`:'/api/books',{...body,request_key:key,revision:editing?.revision||0},editing?'PATCH':'POST');if(b.page_warning){savedReceipt=b;error='';if(editing)editing=b;}else{saved(b);}}catch(e){await showError((e as Error).message);}finally{busy=false;}}
</script>
<div class:with-cover={showCoverPreview&&!!draft.isbn.trim()} class="book-review">
{#if showCoverPreview&&draft.isbn.trim()}<aside class="book-review_cover" aria-label="Book cover preview"><LookupCover isbn={draft.isbn} title={draft.title}/></aside>{/if}
<form class="book-form_wrap" onsubmit={submit} onkeydown={returnToSave}><fieldset aria-label={editing?'Edit book details':'Book details'} disabled={busy||externalBusy||lookupBusy||(!editing&&!!savedReceipt)}>
{#if editing?.isbn}
<div class="book-form_refresh"><button type="button" class="library-button secondary" disabled={busy||lookupBusy||draft.isbn!==editing.isbn} onclick={refresh}>{lookupBusy?'Looking up details…':'Look up fresh details'}</button><p class="library-help">Look up the saved ISBN {editing.isbn}. Review the result before using it; save your changes when ready.</p>
{#if lookupError}<p role="alert" class="library-error">{lookupError}</p>{/if}
{#if fetched}<section aria-label="Fetched book details"><h3>Details from Open Library</h3><p class="library-help">Fetched {new Date(fetched.fetched_at).toLocaleString()}</p>{#if fetched.warning}<p role="status">{fetched.warning}</p>{/if}<dl><dt>Title</dt><dd>{fetched.draft.title}</dd><dt>Subtitle</dt><dd>{fetched.draft.subtitle||'Not provided'}</dd><dt>Authors</dt><dd>{fetched.draft.authors.join(', ')||'Not provided'}</dd><dt>Publisher</dt><dd>{fetched.draft.publisher||'Not provided'}</dd><dt>Publication date</dt><dd>{fetched.draft.publication_date||'Not provided'}</dd></dl><p class="library-help">Using these replaces the title, subtitle, authors, publisher and publication date in this form. Your shelves, copies and cover stay as they are.</p><div class="library-actions"><button type="button" class="library-button secondary" onclick={useDetails}>Use fetched details</button><button type="button" class="library-button secondary" onclick={()=>fetched=null}>Keep my details</button></div></section>{/if}</div>
{/if}<label class="library-field">Title<input required maxlength="500" bind:this={titleInput} bind:value={draft.title}/></label><label class="library-field">Subtitle <span class="library-help">Optional</span><input maxlength="1000" bind:value={draft.subtitle}/></label>{#if !editing&&!savedReceipt&&!draft.isbn.trim()}{#if matches.length}<section class="book-form_matches" aria-label="Possible existing books"><h3>Similar books already here</h3><p class="library-help">Check these before adding another record. Matching titles can be different books or editions; saving stays your choice.</p><ul>{#each matches as match}<li><BookCover title={match.title} coverUrl={match.cover_url} thumbnailUrl={match.cover_thumbnail_url}/><div><a href={`/books/${match.id}/`}>{match.title}</a><small>{[match.authors.join(', '),match.publisher,match.publication_date,match.isbn].filter(Boolean).join(' · ')}</small></div></li>{/each}</ul></section>{/if}{#if matchWarning}<p role="status" class="library-help">{matchWarning}</p>{/if}{/if}<label class="library-field">Authors<span class="library-help">Separate names with commas.</span><input bind:value={authors}/></label><div class="book-form_pair"><label class="library-field">Publisher<input bind:value={draft.publisher}/></label><label class="library-field">Publication date<span class="library-help">A year is fine.</span><input bind:value={draft.publication_date} placeholder="e.g. 1998"/></label></div><label class="library-field">ISBN <span class="library-help">Optional for books without a barcode.</span><input maxlength="32" autocomplete="off" bind:value={draft.isbn}/></label>{#if !editing}<label class="library-field">First copy's shelf<select bind:value={shelf} onchange={()=>shelfTouched=true}><option value="">Unassigned</option>{#each shelves as s}<option value={s.id}>{s.bookcase} / {s.name}</option>{/each}</select></label>{#if preferenceWarning}<p role="status" class="library-notice">{preferenceWarning}</p>{/if}<p class="library-help">This saves one physical copy. An existing ISBN opens its record with the copy count unchanged.</p>{/if}</fieldset>{#if savedReceipt}<p role="status" class="library-notice">Book saved. Its page is still being prepared. <a href={`/books/${savedReceipt.id}/`}>Open the book to retry</a>. Your details are preserved.</p>{/if}{#if error}<p bind:this={errorMessage} tabindex="-1" role="alert" class="library-error">{error}</p>{/if}<button class="library-button" disabled={busy||lookupBusy||externalBusy||preferencesPending||(!editing&&!!savedReceipt)}>{preferencesPending?'Loading shelf…':busy?'Saving…':editing?'Save changes':'Save book and first copy'}</button></form>
</div>
<style>@layer components {.book-review{min-width:0}.book-review.with-cover{display:grid;grid-template-columns:minmax(150px,220px) minmax(0,1fr);gap:var(--space-5);align-items:start}.book-review_cover{position:sticky;top:var(--space-4)}@media(width<48rem){.book-review.with-cover{grid-template-columns:1fr;gap:var(--space-4)}.book-review_cover{position:static;max-width:180px;justify-self:center}}.book-form_wrap{fieldset{display:grid;gap:var(--space-4);border:0;margin:0;padding:0;min-width:0}display:grid;gap:var(--space-4);max-width:42rem}.book-form_matches{display:grid;gap:var(--space-2);h3{font-size:1.125rem;line-height:1.35}ul{display:grid;gap:var(--space-3)}li{display:flex;align-items:center;gap:var(--space-3)}li>div{min-width:0;display:grid;gap:var(--space-1);overflow-wrap:anywhere}}.book-form_refresh{display:grid;gap:var(--space-3);padding:var(--space-4);border:var(--border-width) solid var(--border);border-radius:var(--radius-main);section{display:grid;gap:var(--space-3)}dl{display:grid;grid-template-columns:auto 1fr;gap:var(--space-2);dd{overflow-wrap:anywhere}}}.book-form_pair{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-3);@media(width<48rem){grid-template-columns:1fr}}}</style>
